import{_ as a,o,c as t,a7 as l}from"./chunks/framework.FWlv_suP.js";const f=JSON.parse('{"title":"LocalTell Data Collection","description":"Official data collection information for LocalTell.","frontmatter":{"title":"LocalTell Data Collection","description":"Official data collection information for LocalTell.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/local-tell.md","filePath":"data-collection/local-tell.md"}'),n={name:"data-collection/local-tell.md"};function i(r,e,s,c,d,p){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="localtell-data-collection" tabindex="-1">LocalTell Data Collection <a class="header-anchor" href="#localtell-data-collection" aria-label="Permalink to &quot;LocalTell Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> October 4, 2026</p><h2 id="on-device-processing" tabindex="-1">On-device processing <a class="header-anchor" href="#on-device-processing" aria-label="Permalink to &quot;On-device processing&quot;">​</a></h2><p>With Android location permission, LocalTell reads serving-cell identifiers, including radio technology, MCC/MNC, area code, cell ID, and signal strength. It processes these identifiers on the device for diagnostics. To resolve a Home locality, it first requests one short on-device GNSS fix and compares that coordinate with a locally installed offline SQLite pack. If GPS cannot provide a sufficiently usable coordinate, Home and Easy can offer assisted location only after you explicitly choose it. Assisted location uses Android/Google Play services with a usable network connection; the returned coordinate is still resolved only against the locally installed offline SQLite pack. Easy can also obtain a location only after you choose <strong>Get my location</strong> and can create or decode LocalTell location codes entirely on the device.</p><p>LocalTell does not send location coordinates to the developer and does not perform online reverse geocoding. Outside optional active Journey mode, it does not continuously request location. Journey remains GPS-only: while you have explicitly started it, it periodically requests an on-device GNSS fix and retains a local locality history only when the resolved locality changes. A current Easy location remains in memory only until it is refreshed or the app process ends.</p><p>Optional Journey mode stores local entries containing the time, resolved locality, optional district/state, radio, network code, cell ID, and confidence. Installed-pack metadata and preferences are also stored locally.</p><h2 id="data-received-by-the-developer" tabindex="-1">Data received by the developer <a class="header-anchor" href="#data-received-by-the-developer" aria-label="Permalink to &quot;Data received by the developer&quot;">​</a></h2><p>LocalTell has no account, analytics, advertising, crash reporting, tracking, or developer-operated cloud database. The developer does not receive serving-cell information, approximate-area results, downloaded-pack contents, or Journey history. Support email contains only what you choose to send.</p><h2 id="optional-transfers" tabindex="-1">Optional transfers <a class="header-anchor" href="#optional-transfers" aria-label="Permalink to &quot;Optional transfers&quot;">​</a></h2><p>The app downloads only the offline packs you select and checks for updates over HTTPS. If you explicitly choose assisted location, Android/Google Play services may use the available network to determine the current location; those services apply their own privacy practices. If you explicitly choose Share, Open in Google Maps, Uber, Ola, or Rapido, the selected external app receives the location information needed for that action. Those external destinations apply their own privacy practices.</p><h2 id="google-play-data-safety-context" tabindex="-1">Google Play Data safety context <a class="header-anchor" href="#google-play-data-safety-context" aria-label="Permalink to &quot;Google Play Data safety context&quot;">​</a></h2><p>LocalTell&#39;s serving-cell processing and Journey records remain on the device and are not transmitted to the developer. Play Console declarations must be reviewed for every release and for any future feature that changes these data practices.</p>',12)])])}const y=a(n,[["render",i]]);export{f as __pageData,y as default};
